-- Teams classroom phase 4: scheduling, persistent boards and lesson archive.
create table if not exists public.live_class_schedule_requests (id uuid primary key default gen_random_uuid(), tenant_id uuid not null, module_id uuid references public.modules(id), cohort_reference text not null, lecturer_user_id uuid not null, moderator_user_ids uuid[] not null default '{}', class_template_id uuid references public.teams_class_templates(id), title text not null, starts_at timestamptz not null, ends_at timestamptz not null, status text not null default 'draft', requested_by uuid not null, approved_by uuid, live_session_id uuid references public.live_class_sessions(id), created_at timestamptz not null default now());
create table if not exists public.whiteboard_versions (id uuid primary key default gen_random_uuid(), tenant_id uuid not null, whiteboard_id uuid not null references public.lesson_whiteboards(id) on delete cascade, version_no integer not null, content_reference text, preview_reference text, created_by uuid not null, created_at timestamptz not null default now(), unique(whiteboard_id,version_no));
alter table public.live_class_schedule_requests enable row level security; alter table public.whiteboard_versions enable row level security;
create policy "schedule academic manage" on public.live_class_schedule_requests for all to authenticated using(public.same_tenant(tenant_id) and public.is_academic_manager()) with check(public.same_tenant(tenant_id));
create policy "whiteboard versions tenant read" on public.whiteboard_versions for select to authenticated using(public.same_tenant(tenant_id));